CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_id text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS entities (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, entity_id text NOT NULL, payload jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,kind,entity_id));
CREATE TABLE IF NOT EXISTS sync_events (id bigserial PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, entity_id text NOT NULL, payload jsonb NOT NULL, revision integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,kind,entity_id,revision));
CREATE INDEX IF NOT EXISTS entities_user_kind ON entities(user_id,kind);
ALTER TABLE users ADD COLUMN IF NOT EXISTS email text UNIQUE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS display_name text;
ALTER TABLE users ADD COLUMN IF NOT EXISTS password_hash text;
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
ALTER TABLE users ADD COLUMN IF NOT EXISTS workspace_revision bigint NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS task_shares(owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,task_id text NOT NULL,member_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','declined')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,task_id,member_id),CHECK (owner_id<>member_id));
CREATE INDEX IF NOT EXISTS task_shares_member ON task_shares(member_id,status);
CREATE TABLE IF NOT EXISTS push_tokens(token text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,platform text NOT NULL CHECK (platform IN ('ios','android')),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS push_tokens_user ON push_tokens(user_id);
CREATE TABLE IF NOT EXISTS project_members(owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,project_id text NOT NULL,member_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,project_id,member_id),CHECK(owner_id<>member_id));
CREATE INDEX IF NOT EXISTS project_members_incoming ON project_members(member_id,status);
CREATE TABLE IF NOT EXISTS task_assignments(owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,task_id text NOT NULL,member_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(owner_id,task_id));
CREATE TABLE IF NOT EXISTS task_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,task_id text NOT NULL,author_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,message text NOT NULL CHECK(length(message) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS task_comments_task ON task_comments(owner_id,task_id,created_at);
CREATE TABLE IF NOT EXISTS busy_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,starts_at timestamptz NOT NULL,duration integer NOT NULL CHECK(duration BETWEEN 1 AND 1440));
CREATE TABLE IF NOT EXISTS activities(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,title text NOT NULL,message text NOT NULL,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz);
CREATE INDEX IF NOT EXISTS activities_user ON activities(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS password_resets(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
